// ARCHIVED 2026-09-26: replaced by kubejs/server_scripts/worldgen/ (applied at world load, no manual run).
// Kept for reference only; running this would write kubejs/data files that double-apply.
// Run with `node gen_biome_merges.js` (from this folder). Reads biome_merges.json (the approved
// merges, regenerated by tools/build_biome_merges.py) and writes one additive biome tag file per
// entry to kubejs/data/<ns>/tags/worldgen/biome/<path>.json ("replace": false, so the mod's own
// tag contents are kept and these biomes are simply added). Files written by a previous run that
// are no longer in biome_merges.json are deleted, so /reload falls back to the mod default.

const fs = require('fs');
const path = require('path');

const MERGES_PATH = path.join(__dirname, 'biome_merges.json');
const MANIFEST_PATH = path.join(__dirname, '.generated_biome_tags.json');
const DATA_ROOT = path.join(__dirname, '..', '..', 'data'); // kubejs/data

function tagPath(tagId) {
	const [ns, p] = tagId.split(':');
	return path.join(DATA_ROOT, ns, 'tags', 'worldgen', 'biome', `${p}.json`);
}

function pruneEmptyDirs(dir) {
	while (dir.startsWith(DATA_ROOT) && dir !== DATA_ROOT) {
		if (!fs.existsSync(dir) || fs.readdirSync(dir).length) return;
		fs.rmdirSync(dir);
		dir = path.dirname(dir);
	}
}

const merges = JSON.parse(fs.readFileSync(MERGES_PATH, 'utf8')).tags;
const previous = fs.existsSync(MANIFEST_PATH) ? JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8')) : [];

const written = [];
Object.keys(merges).forEach(tagId => {
	const file = tagPath(tagId);
	fs.mkdirSync(path.dirname(file), { recursive: true });
	fs.writeFileSync(file, JSON.stringify({ replace: false, values: merges[tagId].add }, null, 2) + '\n');
	written.push(path.relative(DATA_ROOT, file));
});

let removed = 0;
previous.filter(f => !written.includes(f)).forEach(f => {
	const abs = path.join(DATA_ROOT, f);
	if (fs.existsSync(abs)) {
		fs.unlinkSync(abs);
		pruneEmptyDirs(path.dirname(abs));
		removed++;
	}
});

fs.writeFileSync(MANIFEST_PATH, JSON.stringify(written.sort(), null, 2) + '\n');
console.log(`${written.length} tag files written, ${removed} stale removed -> kubejs/data/*/tags/worldgen/biome/`);
